<?php
 namespace Pterodactyl\Http\Controllers\Api\Client\Servers; use Pterodactyl\Models\Server; use Illuminate\Http\JsonResponse; use Pterodactyl\Facades\Activity; use Pterodactyl\Jobs\Dezerx\InstallArtifact; use Pterodactyl\Services\Dezerx\FiveM\Artifacts; use Pterodactyl\Services\Dezerx\ServerVariables; use Pterodactyl\Services\Dezerx\FiveM\ServerConfig; use Pterodactyl\Services\Dezerx\Minecraft\ServerFiles; use Pterodactyl\Http\Controllers\Api\Client\ClientApiController; use Pterodactyl\Http\Requests\Api\Client\Servers\Addons\AddonRequest; use Pterodactyl\Http\Requests\Api\Client\Servers\Addons\FiveMWriteRequest; use Pterodactyl\Http\Requests\Api\Client\Servers\Addons\FiveMCacheRequest; use Pterodactyl\Http\Requests\Api\Client\Servers\Addons\FiveMVariableRequest; use Pterodactyl\Http\Requests\Api\Client\Servers\Addons\FiveMArtifactRequest; class FiveMController extends ClientApiController { public function __construct(private readonly Artifacts $artifacts) { parent::__construct(); } public function index(AddonRequest $request, Server $server): JsonResponse { $files = new ServerFiles($server); $config = ServerConfig::locate($files); $catalogue = $this->artifacts->catalogue(); return new JsonResponse([ 'builds' => $catalogue['builds'], 'channels' => $catalogue['channels'], 'error' => $catalogue['error'], 'installed' => ServerConfig::installedBuild($files), 'config' => $config === null ? null : $config['path'], 'gameBuild' => $config === null ? null : ServerConfig::gameBuild($config['contents']), 'gameBuilds' => ServerConfig::GAME_BUILDS, 'txAdmin' => ServerConfig::txAdmin($files, $config['contents'] ?? null), 'cache' => array_column($this->cacheFolders($files, $config), 'path'), ]); } public function artifact(FiveMArtifactRequest $request, Server $server): JsonResponse { $data = $request->validate([ 'build' => ['required', 'string', 'max:12'], ]); $build = $this->artifacts->build((string) $data['build']); if ($build === null) { return new JsonResponse([ 'errors' => [['code' => 'UnknownBuild', 'detail' => 'That build is not one the FiveM artifact server is publishing.']], ], 422); } InstallArtifact::dispatch(server: $server, build: (string) $build['build'], url: (string) $build['url']); Activity::event('server:fivem.artifact') ->property(['build' => $build['build']]) ->log(); return new JsonResponse([ 'queued' => true, 'build' => $build['build'], 'message' => 'The server is being stopped and build ' . $build['build'] . ' installed. This takes a few minutes.', ], 202); } public function txAdmin(FiveMVariableRequest $request, Server $server): JsonResponse { $data = $request->validate([ 'enabled' => ['required', 'boolean'], ]); $files = new ServerFiles($server); $state = ServerConfig::txAdmin($files, null); if (!$state['supported']) { return new JsonResponse([ 'errors' => [['code' => 'NotFiveM', 'detail' => 'This server\'s egg has no ' . ServerConfig::ENABLE_VARIABLE . ' variable, so txAdmin cannot be switched from here. That variable is what a FiveM egg\'s startup command reads.']], ], 422); } if (!$state['editable']) { return new JsonResponse([ 'errors' => [['code' => 'VariableLocked', 'detail' => ServerConfig::ENABLE_VARIABLE . ' is locked on this egg, so only an administrator can change it.']], ], 422); } $enabled = (bool) $data['enabled']; if (!ServerVariables::set($server, (string) $state['variable'], $enabled ? '1' : '0')) { return new JsonResponse([ 'errors' => [['code' => 'WriteFailed', 'detail' => 'That value was refused by the egg\'s own rules for ' . $state['variable'] . '.']], ], 422); } Activity::event('server:fivem.txadmin') ->property(['enabled' => $enabled]) ->log(); $config = ServerConfig::locate($files); return new JsonResponse([ 'txAdmin' => ServerConfig::txAdmin($files, $config['contents'] ?? null), ]); } public function gameBuild(FiveMWriteRequest $request, Server $server): JsonResponse { $data = $request->validate([ 'build' => ['present', 'nullable', 'string', 'max:8'], ]); $build = trim((string) ($data['build'] ?? '')); if ($build !== '' && preg_match('/^\d{3,7}$/', $build) !== 1) { return new JsonResponse([ 'errors' => [['code' => 'InvalidBuild', 'detail' => 'A game build is a number, such as 2802.']], ], 422); } $files = new ServerFiles($server); $config = ServerConfig::locate($files); if ($config === null) { return new JsonResponse([ 'errors' => [['code' => 'NoConfig', 'detail' => 'No server.cfg was found on this server, so there is nothing to write the game build into.']], ], 422); } $updated = ServerConfig::withGameBuild($config['contents'], $build); if (!$files->writeFile($config['path'], $updated)) { return new JsonResponse([ 'errors' => [['code' => 'WriteFailed', 'detail' => 'That could not be written to ' . $config['path'] . '.']], ], 502); } Activity::event('server:fivem.game-build') ->property(['build' => $build === '' ? null : $build, 'file' => $config['path']]) ->log(); return new JsonResponse([ 'gameBuild' => $build === '' ? null : $build, 'config' => $config['path'], ]); } private function cacheFolders(ServerFiles $files, ?array $config): array { $configDir = dirname('/' . ltrim((string) ($config['path'] ?? 'server.cfg'), '/')); $found = []; foreach (array_unique(['/', $configDir]) as $root) { foreach ($files->listFiles($root) ?? [] as $entry) { if (($entry['name'] ?? '') === 'cache' && ($entry['directory'] ?? false)) { $found[] = ['root' => $root, 'path' => rtrim($root, '/') . '/cache']; } } } return $found; } public function cache(FiveMCacheRequest $request, Server $server): JsonResponse { $files = new ServerFiles($server); $state = $files->powerStateOrNull(); if ($state !== 'offline') { return new JsonResponse([ 'errors' => [[ 'code' => 'ServerRunning', 'detail' => $state === null ? 'The node could not be reached, so the cache was left alone.' : 'Stop the server first. FXServer holds its cache open while it runs.', ]], ], 409); } $cleared = []; foreach ($this->cacheFolders($files, ServerConfig::locate($files)) as $folder) { if (!$files->deletePaths($folder['root'], ['cache'])) { return new JsonResponse([ 'errors' => [['code' => 'DeleteFailed', 'detail' => 'The cache at ' . $folder['path'] . ' could not be deleted.']], ], 502); } $cleared[] = $folder['path']; } if ($cleared !== []) { Activity::event('server:fivem.cache')->property(['folders' => $cleared])->log(); } return new JsonResponse(['cleared' => $cleared]); } } 